template void deepmd::tabulate_fusion_se_a_cpu<float>(float* out,
                                                      const float* table,
                                                      const float* table_info,
                                                      const float* em_x,

  1	// SPDX-License-Identifier: LGPL-3.0-or-later
  2	#include "tabulate.h"
  3	
  4	#include <string.h>
  5	
  6	#include <cassert>
  7	#include <iostream>
  8	#include <vector>
  9	/*
 10	    This inline function was designed to get the table info and bias value for
 11	   current input xx! lower:      indicate the lower boundary of the first table;
 12	    upper:      indicate the upper boundary of the first table as well as the
 13	   lower boundary of the second table; max:        indicate the upper boundary
 14	   of the second table; stride0:    indicate the stride of the first table;
 15	    stride1:    indicate the stride of the second table;
 16	    xx:         indicate the inputs value;
 17	    table_idx:  indicate the location of table info of input value xx;
 18	*/
 19	template <typename FPTYPE>
 20	inline void locate_xx(const FPTYPE& lower,
 21	                      const FPTYPE& upper,
 22	                      const FPTYPE& max,
 23	                      const FPTYPE& stride0,
 24	                      const FPTYPE& stride1,
 25	                      FPTYPE& xx,
 26	                      int& table_idx) {
 27	  if (xx < lower) {
 28	    table_idx = 0;
 29	    xx = (FPTYPE)0.;
 30	  } else if (xx < upper) {
 31	    table_idx = (int)((xx - lower) / stride0);
 32	    xx -= (table_idx * stride0 + lower);
 33	  } else if (xx < max) {
 34	    int first_stride = int((upper - lower) / stride0);
 35	    table_idx = first_stride + (int)((xx - upper) / stride1);
 36	    xx -= ((table_idx - first_stride) * stride1 + upper);
 37	  } else {
 38	    table_idx =
 39	        int((upper - lower) / stride0) + (int)((max - upper) / stride1) - 1;
 40	    xx = (FPTYPE)0.;
 41	  }
 42	}
 43	
 44	template <typename FPTYPE>
 45	inline void locate_xx_se_t(const FPTYPE& lower,
 46	                           const FPTYPE& upper,
 47	                           const FPTYPE& min,
 48	                           const FPTYPE& max,
 49	                           const FPTYPE& stride0,
 50	                           const FPTYPE& stride1,
 51	                           FPTYPE& xx,
 52	                           int& table_idx) {
 53	  if (xx < min) {
 54	    table_idx = 0;
 55	    xx = (FPTYPE)0.;
 56	  } else if (xx < lower) {
 57	    table_idx = (int)((xx - min) / stride1);
 58	    xx -= (table_idx * stride1 + min);
 59	  } else if (xx < upper) {
 60	    int first_stride = int((lower - min) / stride1);
 61	    table_idx = first_stride + (int)((xx - lower) / stride0);
 62	    xx -= ((table_idx - first_stride) * stride0 + lower);
 63	  } else if (xx < max) {
 64	    int first_stride =
 65	        int((lower - min) / stride1) + int((upper - lower) / stride0);
 66	    table_idx = first_stride + (int)((xx - upper) / stride1);
 67	    xx -= ((table_idx - first_stride) * stride1 + upper);
 68	  } else {
 69	    table_idx = int((lower - min) / stride1) + int((upper - lower) / stride0) +
 70	                (int)((max - upper) / stride1) - 1;
 71	    xx = (FPTYPE)0.;
 72	  }
 73	}
 74	
 75	template <typename FPTYPE>
 76	inline FPTYPE dot(FPTYPE a[4], FPTYPE b[4]) {
 77	  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2] + a[3] * b[3];
 78	}
 79	
 80	template <typename FPTYPE>
 81	void deepmd::tabulate_fusion_se_a_cpu(FPTYPE* out,
 82	                                      const FPTYPE* table,
 83	                                      const FPTYPE* table_info,
 84	                                      const FPTYPE* em_x,
 85	                                      const FPTYPE* em,
 86	                                      const FPTYPE* two_embed,
 87	                                      const int nloc,
 88	                                      const int nnei,
 89	                                      const int last_layer_size,
 90	                                      const bool is_sorted) {
 91	  bool enable_se_atten = two_embed != nullptr;
 92	  memset(out, 0, sizeof(FPTYPE) * nloc * 4 * last_layer_size);
 93	  const FPTYPE lower = table_info[0];
 94	  const FPTYPE upper = table_info[1];
 95	  const FPTYPE _max = table_info[2];
 96	  const FPTYPE stride0 = table_info[3];
 97	  const FPTYPE stride1 = table_info[4];
 98	// for every atom, execute a small manual gemm ~
 99	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
100	#pragma omp parallel for
101	  for (int ii = 0; ii < nloc; ii++) {
102	    FPTYPE ll[4] = {0};
103	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
104	    bool unloop = false;
105	    for (int jj = 0; jj < nnei; jj++) {
106	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
107	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
108	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
109	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
110	      FPTYPE xx = em_x[ii * nnei + jj];
111	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
112	        unloop = true;
113	      }
114	      int table_idx = 0;
115	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
116	      for (int kk = 0; kk < last_layer_size; kk++) {
117	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
118	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
119	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
120	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
121	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
122	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
123	        FPTYPE var =
124	            a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
125	        if (enable_se_atten) {
126	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
127	                               jj * last_layer_size + kk];
128	          var = var * t + var;
129	        }
130	
131	        if (unloop) {
132	          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
133	              (nnei - jj) * var * ll[0];
134	          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
135	              (nnei - jj) * var * ll[1];
136	          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
137	              (nnei - jj) * var * ll[2];
138	          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
139	              (nnei - jj) * var * ll[3];
140	        } else {
141	          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
142	              var * ll[0];
143	          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
144	              var * ll[1];
145	          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
146	              var * ll[2];
147	          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
148	              var * ll[3];
149	        }
150	      }
151	      if (unloop) {
152	        break;
153	      }
154	    }
155	  }
156	}
