694	template <typename FPTYPE>
695	void deepmd::tabulate_fusion_se_r_cpu(FPTYPE* out,
696	                                      const FPTYPE* table,
697	                                      const FPTYPE* table_info,
698	                                      const FPTYPE* em,
699	                                      const int nloc,
700	                                      const int nnei,
701	                                      const int last_layer_size) {
702	  memset(out, 0, sizeof(FPTYPE) * nloc * nnei * last_layer_size);
703	  const FPTYPE lower = table_info[0];
704	  const FPTYPE upper = table_info[1];
705	  const FPTYPE _max = table_info[2];
706	  const FPTYPE stride0 = table_info[3];
707	  const FPTYPE stride1 = table_info[4];
708	// for every atom, execute a small manual gemm ~
709	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
710	#pragma omp parallel for
711	  for (int ii = 0; ii < nloc; ii++) {
712	    for (int jj = 0; jj < nnei; jj++) {
713	      FPTYPE xx = em[ii * nnei + jj];
714	      int table_idx = 0;
715	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
716	      for (int kk = 0; kk < last_layer_size; kk++) {
717	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
718	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
719	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
720	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
721	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
722	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
723	        out[ii * last_layer_size * nnei + jj * last_layer_size + kk] =
724	            a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
725	      }
726	    }
727	  }
728	}
