730	template <typename FPTYPE>
731	void deepmd::tabulate_fusion_se_r_grad_cpu(FPTYPE* dy_dem,
732	                                           const FPTYPE* table,
733	                                           const FPTYPE* table_info,
734	                                           const FPTYPE* em,
735	                                           const FPTYPE* dy,
736	                                           const int nloc,
737	                                           const int nnei,
738	                                           const int last_layer_size) {
739	  memset(dy_dem, 0, sizeof(FPTYPE) * nloc * nnei);
740	  FPTYPE const lower = table_info[0];
741	  FPTYPE const upper = table_info[1];
742	  FPTYPE const _max = table_info[2];
743	  FPTYPE const stride0 = table_info[3];
744	  FPTYPE const stride1 = table_info[4];
745	// for every atom, execute a small gemm~
746	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
747	#pragma omp parallel for
748	  for (int ii = 0; ii < nloc; ii++) {
749	    for (int jj = 0; jj < nnei; jj++) {
750	      // construct the dy/dx
751	      FPTYPE xx = em[ii * nnei + jj];
752	      int table_idx = 0;
753	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
754	      FPTYPE grad = (FPTYPE)0.0;
755	      for (int kk = 0; kk < last_layer_size; kk++) {
756	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
757	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
758	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
759	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
760	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
761	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
762	        grad += (a1 + ((FPTYPE)2. * a2 +
763	                       ((FPTYPE)3. * a3 +
764	                        ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
765	                           xx) *
766	                          xx) *
767	                dy[ii * last_layer_size * nnei + jj * last_layer_size + kk];
768	      }
769	      dy_dem[ii * nnei + jj] = grad;
770	    }
771	  }
772	}
