795	      int table_idx = 0;
796	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
797	      for (int kk = 0; kk < last_layer_size; kk++) {
798	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
799	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
800	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
801	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
802	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
803	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
804	        FPTYPE var_grad =
