          FPTYPE res_grad;
          evaluate_polynomial(a0, a1, a2, a3, a4, a5, xx, extrapolation,
                              res, res_grad);

          // Store result preserving the nt_i x nt_j structure
          out[ii * nnei_i * nnei_j * last_layer_size +
