#include \"tabulate.h\"

#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

constexpr int L = 4;

void require_close(double actual, double expected, double atol,
                   const std::string& label) {
  const double error = std::abs(actual - expected);
  if ("'!std::isfinite(actual) || !std::isfinite(expected) || error > atol) {
    std::cerr << label << ": actual=" << actual << " expected=" << expected
              << " error=" << error << " tolerance=" << atol << "'"\\n\";
    throw std::runtime_error(label);
  }
}

double dot(const std::vector<double>& a, const std::vector<double>& b) {
  double out = 0.0;
  for (std::size_t i = 0; i < a.size(); ++i) out += a[i] * b[i];
  return out;
}

std::vector<double> coefficients(double base, int layer) {
  const double A = 0.31 + 0.07 * layer;
  const double B = -0.22 + 0.04 * layer;
  const double C = 0.08 - 0.01 * layer;
  const double D = -0.013 + 0.002 * layer;
  return {A + B * base + C * base * base + D * base * base * base,
          B + 2.0 * C * base + 3.0 * D * base * base,
          C + 3.0 * D * base, D, 0.0, 0.0};
}

std::vector<double> make_table(const std::vector<double>& bases) {
  std::vector<double> table(bases.size() * L * 6);
  for (std::size_t segment = 0; segment < bases.size(); ++segment) {
    for (int layer = 0; layer < L; ++layer) {
      const auto coeff = coefficients(bases[segment], layer);
      for (int c = 0; c < 6; ++c) {
        table[(segment * L + layer) * 6 + c] = coeff[c];
      }
    }
  }
  return table;
}

std::vector<double> regular_bases(double lower, double upper, double max,
                                  double stride0, double stride1) {
  std::vector<double> bases;
  for (int i = 0; i < int((upper - lower) / stride0); ++i)
    bases.push_back(lower + i * stride0);
  for (int i = 0; i < int((max - upper) / stride1); ++i)
    bases.push_back(upper + i * stride1);
  return bases;
}

std::vector<double> tensor_bases(double lower, double upper, double max,
                                 double stride0, double stride1) {
  std::vector<double> bases;
  for (int i = 0; i < int((lower + max) / stride1); ++i)
    bases.push_back(-max + i * stride1);
  for (int i = 0; i < int((upper - lower) / stride0); ++i)
    bases.push_back(lower + i * stride0);
  for (int i = 0; i < int((max - upper) / stride1); ++i)
    bases.push_back(upper + i * stride1);
  return bases;
}

double radial_value(const std::vector<double>& table,
                    const std::vector<double>& info,
                    const std::vector<double>& weights, double x) {
  std::vector<double> out(L);
  deepmd::tabulate_fusion_se_r_cpu(out.data(), table.data(), info.data(), &x,
                                   1, 1, L);
  return dot(out, weights);
}

void check_radial(const std::vector<double>& table,
                  const std::vector<double>& info,
                  const std::vector<double>& points) {
  const std::vector<double> weights{0.7, -0.2, 0.11, -0.37};
  constexpr double h = 1e-6;
  for (double x : points) {
    double grad = 0.0;
    deepmd::tabulate_fusion_se_r_grad_cpu(&grad, table.data(), info.data(), &x,
                                          weights.data(), 1, 1, L);
    const double fd = (radial_value(table, info, weights, x + h) -
                       radial_value(table, info, weights, x - h)) /
                      (2.0 * h);
    require_close(grad, fd, 2e-7, \"se_r finite difference\");

    const double z = -0.43;
    std::vector<double> adjoint(L);
    deepmd::tabulate_fusion_se_r_grad_grad_cpu(
        adjoint.data(), table.data(), info.data(), &x, &z, 1, 1, L);
    require_close(z * grad, dot(adjoint, weights), 2e-12,
                  \"se_r grad-grad adjoint\");
  }

  double x1 = info[2] + 1.0, x2 = info[2] + 100.0;
  double g1 = 0.0, g2 = 0.0;
  deepmd::tabulate_fusion_se_r_grad_cpu(&g1, table.data(), info.data(), &x1,
                                        weights.data(), 1, 1, L);
  deepmd::tabulate_fusion_se_r_grad_cpu(&g2, table.data(), info.data(), &x2,
                                        weights.data(), 1, 1, L);
  require_close(g1, g2, 2e-12, \"se_r controlled upper continuation\");
}

void check_angular(const std::vector<double>& table,
                   const std::vector<double>& info,
                   const std::vector<double>& points) {
  const std::vector<double> dy{0.2, -0.1, 0.7, -0.3,
                               -0.4, 0.6, 0.1, 0.5,
                               0.8, -0.2, -0.5, 0.3,
                               -0.7, 0.4, 0.9, -0.6};
  const std::vector<double> base_env{1.0, -0.2, 0.3, -0.4};
  const std::vector<double> base_two{0.15, -0.25, 0.35, -0.1};
  constexpr double h = 1e-6;

  auto value = [&](double x, const std::vector<double>& env,
                   const std::vector<double>& two) {
    std::vector<double> out(4 * L);
    deepmd::tabulate_fusion_se_a_cpu(out.data(), table.data(), info.data(), &x,
                                     env.data(), two.data(), 1, 1, L, false);
    return dot(out, dy);
  };

  for (double x : points) {
    std::vector<double> dx(1), dem(4), dtwo(L);
    deepmd::tabulate_fusion_se_a_grad_cpu(
        dx.data(), dem.data(), dtwo.data(), table.data(), info.data(), &x,
        base_env.data(), base_two.data(), dy.data(), 1, 1, L, false);
    const double fd = (value(x + h, base_env, base_two) -
                       value(x - h, base_env, base_two)) /
                      (2.0 * h);
    require_close(dx[0], fd, 3e-7, \"se_a x finite difference\");

    for (int q = 0; q < 4; ++q) {
      auto plus = base_env, minus = base_env;
      plus[q] += h;
      minus[q] -= h;
      require_close(dem[q], (value(x, plus, base_two) -
                             value(x, minus, base_two)) /
                                (2.0 * h),
                    3e-9, \"se_a env finite difference\");
    }
    for (int k = 0; k < L; ++k) {
      auto plus = base_two, minus = base_two;
      plus[k] += h;
      minus[k] -= h;
      require_close(dtwo[k], (value(x, base_env, plus) -
                              value(x, base_env, minus)) /
                                 (2.0 * h),
                    3e-9, \"se_a attention finite difference\");
    }

    const std::vector<double> zx{0.37};
    const std::vector<double> zem{-0.2, 0.4, -0.1, 0.3};
    const std::vector<double> ztwo{0.11, -0.23, 0.31, -0.17};
    std::vector<double> adjoint(4 * L);
    deepmd::tabulate_fusion_se_a_grad_grad_cpu(
        adjoint.data(), table.data(), info.data(), &x, base_env.data(),
        base_two.data(), zx.data(), zem.data(), ztwo.data(), 1, 1, L, false);
    const double lhs = dot(zx, dx) + dot(zem, dem) + dot(ztwo, dtwo);
    require_close(lhs, dot(adjoint, dy), 3e-12,
                  \"se_a grad-grad adjoint\");
  }
}

void check_tensor(const std::vector<double>& table,
                  const std::vector<double>& info,
                  const std::vector<double>& points) {
  const std::vector<double> dy{0.7, -0.2, 0.11, -0.37};
  constexpr double h = 1e-6;
  auto value = [&](double x) {
    std::vector<double> out(L);
    deepmd::tabulate_fusion_se_t_cpu(out.data(), table.data(), info.data(), &x,
                                     &x, 1, 1, 1, L);
    return dot(out, dy);
  };
  auto tebd_value = [&](double x) {
    std::vector<double> out(L);
    deepmd::tabulate_fusion_se_t_tebd_cpu(
        out.data(), table.data(), info.data(), &x, &x, 1, 1, 1, L);
    return dot(out, dy);
  };

  for (double x : points) {
    double dx = 0.0, dem = 0.0;
    deepmd::tabulate_fusion_se_t_grad_cpu(
        &dx, &dem, table.data(), info.data(), &x, &x, dy.data(), 1, 1, 1, L);
    const double fd = (value(x + h) - value(x - h)) / (2.0 * h);
    require_close(dx + dem, fd, 4e-7, \"se_t finite difference\");

    const double zx = 0.29, zem = -0.41;
    std::vector<double> adjoint(L);
    deepmd::tabulate_fusion_se_t_grad_grad_cpu(
        adjoint.data(), table.data(), info.data(), &x, &x, &zx, &zem, 1, 1, 1,
        L);
    require_close(zx * dx + zem * dem, dot(adjoint, dy), 2e-12,
                  \"se_t grad-grad adjoint\");

    double tebd_dx = 0.0;
    deepmd::tabulate_fusion_se_t_tebd_grad_cpu(
        &tebd_dx, table.data(), info.data(), &x, &x, dy.data(), 1, 1, 1, L);
    const double tebd_fd =
        (tebd_value(x + h) - tebd_value(x - h)) / (2.0 * h);
    require_close(tebd_dx, tebd_fd, 3e-7, \"se_t_tebd finite difference\");

    const double z = -0.53;
    deepmd::tabulate_fusion_se_t_tebd_grad_grad_cpu(
        adjoint.data(), table.data(), info.data(), &x, &x, &z, 1, 1, 1, L);
    require_close(z * tebd_dx, dot(adjoint, dy), 2e-12,
                  \"se_t_tebd grad-grad adjoint\");
  }
}

}  // namespace

