  const std::vector<double> bases={-1.,-.75,-.5,0.,.5};
  std::vector<double> table(bases.size()*6);
  for(int i=0;i<(int)bases.size();++i){table[i*6]=2.+3.*bases[i];table[i*6+1]=3.;}
  for(double x:std::vector<double>{-2.,-1.,.25,1.,3.}){
    double out=0.,grad=0.,dy=1.;
    deepmd::tabulate_fusion_se_t_tebd_cpu(&out,table.data(),info,&x,&x,1,1,1,L);
    deepmd::tabulate_fusion_se_t_tebd_grad_cpu(&grad,table.data(),info,&x,&x,&dy,1,1,1,L);
    if(std::abs(out-(2.+3.*x))>1e-12 || std::abs(grad-3.)>1e-12) return 1;
  }
  std::cout<<\"compact tensor endpoint check passed\\n\";
}
